1	package warranty
2	
3	import (
4		"fmt"
5		"sync"
6		"time"
7	)
8	
9	// Product 是登记的产品保修信息。
10	type Product struct {
11		// ID 是唯一产品编号。
12		ID string
13		// PurchaseTime 是购买时刻。
14		PurchaseTime time.Time
15		// WarrantyDays 是保修天数，必须为正整数；保修期自购买时刻起，每天按二十四小时计算。
16		WarrantyDays int
17		// ExcludedCodes 是除外故障代码集合；命中代码的请求一律拒绝。
18		ExcludedCodes map[string]struct{}
19	}
20	
21	// Part 是登记的备件及其库存。
22	type Part struct {
23		// ID 是唯一备件编号。
24		ID string
25		// Stock 是当前剩余实物库存，被成功使用的承诺分批扣减。
26		Stock int
27	}
28	
29	// Request 是提交的保修请求，指定产品和故障代码。
30	type Request struct {
31		// ID 是唯一请求编号。
32		ID string
33		// ProductID 是关联的产品编号。
34		ProductID string
35		// FaultCode 是故障代码，不能为空。
36		FaultCode string
37	}
38	
39	// CommitmentStatus 是承诺的当前状态。
40	type CommitmentStatus string
41	
42	const (
43		// CommitmentActive 表示承诺有效：未取消且未到期。
44		CommitmentActive CommitmentStatus = "active"
45		// CommitmentCanceled 表示承诺已被取消。
46		CommitmentCanceled CommitmentStatus = "canceled"
47		// CommitmentExpired 表示承诺已到期，余量自动释放。
48		CommitmentExpired CommitmentStatus = "expired"
49	)
50	
51	// Commitment 是一笔备件承诺。
52	type Commitment struct {
53		// ID 是全局唯一的提交编号。
54		ID string
55		// RequestID 是关联的请求编号。
56		RequestID string
57		// PartID 是预留的备件编号。
58		PartID string
59		// Quantity 是原定承诺数量（正整数）。
60		Quantity int
61		// Used 是已成功使用的累计数量。
62		Used int
63		// Expiry 是到期时刻；当前时刻等于或晚于它时承诺到期，余量释放。
64		Expiry time.Time
65		// Canceled 表示是否已被取消。
66		Canceled bool
67		// Expired 表示到期是否已被确认。到期确认是不可逆的结果：一经确认，
68		// 未用占用永久释放，之后即使传入更早的当前时刻也仍视为到期，不能重新
69		// 占用已释放给其他请求的数量。未确认前仅在当次时刻达到到期时刻时
70		// （库存查询、请求查询、新预留核算、新使用判断）就本次涉及的承诺确认。
71		// 幂等重试、参数非法或引用对象不存在而提前失败的调用不确认到期。
72		Expired bool
73	}
74	
75	// Unused 返回未用数量。
76	func (c *Commitment) Unused() int { return c.Quantity - c.Used }
77	
78	// confirmExpiryLocked 在已持锁的情况下按本次当前时刻确认单笔承诺到期。
79	// 仅确认本次操作涉及的承诺：未取消、尚未确认且当前时刻已达到到期时刻时
80	// 置位 Expired；该结果不可逆。已取消的承诺保持 canceled，不确认到期。
81	func (s *Store) confirmExpiryLocked(c *Commitment, now time.Time) {
82		if c.Canceled || c.Expired {
83			return
84		}
85		if !now.Before(c.Expiry) {
86			c.Expired = true
87		}
88	}
89	
90	// confirmPartExpiriesLocked 确认指定备件下全部已到期但尚未确认的承诺。
91	func (s *Store) confirmPartExpiriesLocked(partID string, now time.Time) {
92		for _, c := range s.commitments {
93			if c.PartID == partID {
94				s.confirmExpiryLocked(c, now)
95			}
96		}
97	}
98	
99	// confirmRequestExpiriesLocked 确认指定请求下全部已到期但尚未确认的承诺。
100	func (s *Store) confirmRequestExpiriesLocked(requestID string, now time.Time) {
101		for _, c := range s.commitments {
102			if c.RequestID == requestID {
103				s.confirmExpiryLocked(c, now)
104			}
105		}
106	}
107	
108	// Status 返回承诺的当前状态。
109	// 已确认到期不可逆：即使传入更早的当前时刻也显示 expired；状态不要求
110	// 调用时刻递增。取消优先于到期，已取消的记录始终显示 canceled。
111	func (c *Commitment) Status(now time.Time) CommitmentStatus {
112		switch {
113		case c.Canceled:
114			return CommitmentCanceled
115		case c.Expired:
116			return CommitmentExpired
117		case !now.Before(c.Expiry):
118			return CommitmentExpired
119		default:
120			return CommitmentActive
121		}
122	}
123	
124	// Usage 是一次成功的承诺使用记录。
125	type Usage struct {
126		// ID 是全局唯一的使用编号。
127		ID string
128		// CommitmentID 是被扣减的承诺编号。
129		CommitmentID string
130		// Quantity 是本次使用的正整数数量。
131		Quantity int
132	}
133	
134	// Store 保存全部登记信息与承诺。所有方法均为并发安全。
135	type Store struct {
136		mu          sync.Mutex
137		products    map[string]*Product
138		parts       map[string]*Part
139		requests    map[string]*Request
140		commitments map[string]*Commitment
141		usages      map[string]*Usage
142		// firstResults 保存每个承诺编号首次预留成功时返回的承诺快照（已用数量为零、
143		// 未取消）。原样重试取回它，不随分批使用、取消或到期改变。
144		firstResults map[string]Commitment
145		// history 保存按请求分组的预留处理历史，仅存在于当前仓库实例中。
146		history map[string][]HistoryRecord
147	}
148	
149	// NewStore 创建一个空的保修备件仓库。
150	func NewStore() *Store {
151		return &Store{
152			products:     make(map[string]*Product),
153			parts:        make(map[string]*Part),
154			requests:     make(map[string]*Request),
155			commitments:  make(map[string]*Commitment),
156			usages:       make(map[string]*Usage),
157			firstResults: make(map[string]Commitment),
158			history:      make(map[string][]HistoryRecord),
159		}
160	}
161	
162	// RegisterProduct 登记产品：购买时刻、保修天数和除外故障代码。
163	// 编号重复时返回 ErrDuplicateID 且保留原记录。
164	func (s *Store) RegisterProduct(id string, purchaseTime time.Time, warrantyDays int, excludedCodes []string) error {
165		if id == "" {
166			return fmt.Errorf("%w: product id must not be empty", ErrInvalidParam)
167		}
168		if warrantyDays <= 0 {
169			return fmt.Errorf("%w: warranty days must be a positive integer", ErrInvalidParam)
170		}
171		s.mu.Lock()
172		defer s.mu.Unlock()
173		if _, ok := s.products[id]; ok {
174			return fmt.Errorf("%w: product %q", ErrDuplicateID, id)
175		}
176		codes := make(map[string]struct{}, len(excludedCodes))
177		for _, c := range excludedCodes {
178			if c == "" {
179				return fmt.Errorf("%w: excluded fault code must not be empty", ErrInvalidParam)
180			}
181			codes[c] = struct{}{}
182		}
183		s.products[id] = &Product{
184			ID:            id,
185			PurchaseTime:  purchaseTime,
186			WarrantyDays:  warrantyDays,
187			ExcludedCodes: codes,
188		}
189		return nil
190	}
191	
192	// RegisterPart 登记备件及其非负整数初始库存。
193	// 编号重复时返回 ErrDuplicateID 且保留原记录。
194	func (s *Store) RegisterPart(id string, initialStock int) error {
195		if id == "" {
196			return fmt.Errorf("%w: part id must not be empty", ErrInvalidParam)
197		}
198		if initialStock < 0 {
199			return fmt.Errorf("%w: initial stock must be a non-negative integer", ErrInvalidParam)
200		}
201		s.mu.Lock()
202		defer s.mu.Unlock()
203		if _, ok := s.parts[id]; ok {
204			return fmt.Errorf("%w: part %q", ErrDuplicateID, id)
205		}
206		s.parts[id] = &Part{ID: id, Stock: initialStock}
207		return nil
208	}
209	
210	// SubmitRequest 提交保修请求，指定产品和故障代码。
211	// 编号重复时返回 ErrDuplicateID 且保留原记录。
212	func (s *Store) SubmitRequest(id, productID, faultCode string) error {
213		if id == "" {
214			return fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
215		}
216		if faultCode == "" {
217			return fmt.Errorf("%w: fault code must not be empty", ErrInvalidParam)
218		}
219		s.mu.Lock()
220		defer s.mu.Unlock()
221		if _, ok := s.requests[id]; ok {
222			return fmt.Errorf("%w: request %q", ErrDuplicateID, id)
223		}
224		s.requests[id] = &Request{ID: id, ProductID: productID, FaultCode: faultCode}
225		return nil
226	}
227	
228	// Product 返回指定编号的产品副本，不存在时返回 ErrNotFound。
229	func (s *Store) Product(id string) (Product, error) {
230		s.mu.Lock()
231		defer s.mu.Unlock()
232		p, ok := s.products[id]
233		if !ok {
234			return Product{}, fmt.Errorf("%w: product %q", ErrNotFound, id)
235		}
236		cp := *p
237		cp.ExcludedCodes = make(map[string]struct{}, len(p.ExcludedCodes))
238		for k := range p.ExcludedCodes {
239			cp.ExcludedCodes[k] = struct{}{}
240		}
241		return cp, nil
242	}
243	
244	// Part 返回指定编号的备件副本，不存在时返回 ErrNotFound。
245	func (s *Store) Part(id string) (Part, error) {
246		s.mu.Lock()
247		defer s.mu.Unlock()
248		p, ok := s.parts[id]
249		if !ok {
250			return Part{}, fmt.Errorf("%w: part %q", ErrNotFound, id)
251		}
252		return *p, nil
253	}
254	
255	// Request 返回指定编号的请求副本，不存在时返回 ErrNotFound。
256	func (s *Store) Request(id string) (Request, error) {
257		s.mu.Lock()
258		defer s.mu.Unlock()
259		r, ok := s.requests[id]
260		if !ok {
261			return Request{}, fmt.Errorf("%w: request %q", ErrNotFound, id)
262		}
263		return *r, nil
264	}
265	
266	// Commitment 返回指定编号的承诺副本，不存在时返回 ErrNotFound。
267	func (s *Store) Commitment(id string) (Commitment, error) {
268		s.mu.Lock()
269		defer s.mu.Unlock()
270		c, ok := s.commitments[id]
271		if !ok {
272			return Commitment{}, fmt.Errorf("%w: commitment %q", ErrNotFound, id)
273		}
274		return *c, nil
275	}
276

