			t.Fatalf("span = %d seconds (sub saturated %v), want %d", got, d, int64(106752)*24*3600)
		}
	}
	// 同一时刻换时区表示，截止时刻仍是同一实际时刻。
	e2, err := s.Evaluate("r", purchase.In(time.UTC))
	if err != nil {
		t.Fatal(err)
	}
