// 改成自然日、不把截止时刻对齐到当地零点。
func TestLongWarrantyExpiryPrecisionAndZone(t *testing.T) {
	loc := time.FixedZone("UTC+8", 8*3600)
	purchase := time.Date(2026, 1, 1, 0, 0, 0, 123456789, loc)
	s := NewStore()
	if err := s.RegisterProduct("p", purchase, 106752, nil); err != nil {
