	if got := e.WarrantyExpiry.Unix() - purchase.Unix(); got != int64(106752)*24*3600 {
		t.Fatalf("span = %d seconds, want %d", got, int64(106752)*24*3600)
	}
	// 同一时刻换时区表示，截止时刻仍是同一实际时刻。
