		t.Fatal(err)
	}
	elig, err := s.Evaluate("r", purchase)
	if err != nil {
		t.Fatal(err)
	}
	expiry := elig.WarrantyExpiry
	commitExpiry := purchase.Add(24 * time.Hour)

	// 截止时刻前一秒：预留成功。
	if _, err := s.Reserve("c1", "r", "sp", 1, commitExpiry, expiry.Add(-time.Second)); err != nil {
